  "votes": [
    {
      "item": "i01",
      "choice": "v1",
      "reason": "La résolution 2026-01-06, page 5, autorise expressément la vente du lot 4 342 594 par invitation à soumissionner, un acte foncier inclus au corrigé."
    },
    {
      "item": "i02",
      "choice": "v1",
      "reason": "La page 8 atteste l’avis de motion donné le 13 janvier 2026 pour le règlement 419 permettant l’agriculture sans élevage à l’intérieur des bâtiments de la zone 31-C."
    },
    {
      "item": "i03",
      "choice": "v1",
      "reason": "La résolution 2026-01-15 commence page 8 sous l’intitulé cité et adopte le premier projet du règlement 419, étape distincte de l’avis de motion."
    },
    {
      "item": "i04",
      "choice": "v1",
      "reason": "La résolution 2026-01-16, page 10, refuse explicitement l’amendement au zonage demandé pour le 247, rue des Forgerons, conformément à la règle voulant qu’un refus reste un refus."
    },
    {
      "item": "i05",
      "choice": "v1",
      "reason": "La résolution 2026-01-17, page 10, porte l’intitulé cité du PPCMOI au 176, rue du Bord-de-l’Eau et refuse explicitement le projet d’hébergement touristique et commercial."
    },
    {
      "item": "i06",
      "choice": "v1",
      "reason": "La résolution 2026-01-31, page 14, inclut expressément le lot 4 344 119 dans la fermeture du chemin municipal et la cession gratuite au MELCCFP."
    },
    {
      "item": "i07",
      "choice": "v1",
      "reason": "La résolution 2026-01-31, page 14, inclut expressément le lot 6 683 045 dans la fermeture et la cession gratuite, ce lot constituant un objet foncier distinct explicitement nommé."
    },
    {
      "item": "i08",
      "choice": "v1",
      "reason": "La résolution 2026-01-31, page 14, prévoit expressément une servitude en faveur de Tadoussac pour le réseau d’aqueduc situé sur les lots visés."
    },
    {
      "item": "i09",
      "choice": "v1",
      "reason": "La résolution 2026-01-31, page 14, accepte la cession gratuite au MELCCFP du barrage et identifie les immeubles par l’acte no 62 447."
    },
    {
      "item": "i10",
      "choice": "v1",
      "reason": "Le dispositif de la résolution 2026-01-32, page 15, adopte expressément le règlement 415 citant la Maison du Tourisme au 197, rue des Pionniers comme immeuble patrimonial."
    },
    {
      "item": "i11",
      "choice": "absent",
      "reason": "La page 9 annonce une consultation future dans les attendus du premier projet 419, fait complémentaire qui ne constitue pas une étape distincte constatée dans cette séance."
    }
  ]
}
